const input = $input.first()?.json || {};
const clean = (value, fallback = '') => String(value ?? fallback).trim();
const list = (value) => Array.from(new Set((Array.isArray(value) ? value : String(value ?? '').split(',')).map(v => clean(v)).filter(Boolean)));
const isoDate = (value, name) => {
  const raw = clean(value);
  if (!raw) return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(raw) || Number.isNaN(Date.parse(`${raw}T00:00:00Z`))) throw new Error(`${name} must use YYYY-MM-DD.`);
  return raw;
};
const enabled = String($env.N8N_ENABLE_OPENBESLUITVORMING || 'true').trim().toLowerCase() !== 'false';
const query = clean(input.query || input.question || input.input || input.text);
const dateFrom = isoDate(input.date_from, 'date_from');
const dateTo = isoDate(input.date_to, 'date_to');
if (dateFrom && dateTo && dateFrom > dateTo) throw new Error('date_from mag niet na date_to liggen.');
const dateOnly = !query && Boolean(dateFrom || dateTo);
if (!query && !dateOnly) throw new Error('Geef een inhoudelijk onderwerp in query, of gebruik date_from/date_to voor een datumoverzicht zonder onderwerp.');
const requestedSources = list(input.source_keys || input.source_key || input.organization);
const defaultSources = list($env.OPENBESLUITVORMING_DEFAULT_SOURCES || $env.OPENBESLUITVORMING_DEFAULT_SOURCE || 'provincie_limburg');
const sourceKeys = requestedSources.length ? requestedSources : defaultSources;
return [{ json: {
  query: query || null,
  enabled,
  date_only: dateOnly,
  source_keys: sourceKeys,
  // Retrieval breadth is deliberately fixed. The adaptive relevance gate below decides how many documents are returned.
  top_k: 100,
  candidate_limit: 500,
  include_content: input.include_content === true,
  date_from: dateFrom,
  date_to: dateTo,
  suppliers: list(input.suppliers || input.supplier),
  entity_types: list(input.entity_types || input.entity_type || input.document_type || 'Document').map(value => value.toLowerCase()).map(value => value === 'document' ? 'Document' : value === 'meeting' ? 'Meeting' : value === 'motion' ? 'Motion' : value === 'recording' ? 'Recording' : value),
  document_classifications: list(input.document_classifications || input.document_classification),
  meeting_ids: list(input.meeting_ids || input.meeting_id),
  document_ids: list(input.document_ids || input.document_id),
  collection: clean(input.collection || $env.OPENBESLUITVORMING_COLLECTION, 'openraadsinformatie_v1'),
  qdrant_base: clean(input.qdrant_base || $env.OPENBESLUITVORMING_QDRANT_URL, 'http://qdrant:6333').replace(/\/$/, ''),
  litellm_base: clean(input.litellm_base || $env.LITELLM_URL, 'http://litellm:4000').replace(/\/$/, ''),
  embedding_model: clean(input.embedding_model || $env.OPENBESLUITVORMING_EMBEDDING_MODEL, 'govchat-embedding'),
  default_artifact_source: clean($env.OPENBESLUITVORMING_DEFAULT_SOURCE, 'provincie_limburg')
} }];

const request = $('2. Validate Search Request').first().json;
const response = $input.first()?.json || {};
const body = response.body || response.data || response;
const status = Number(response.statusCode || response.status || response.error?.httpCode || response.error?.statusCode || 0);
const vectors = body?.result?.config?.params?.vectors;
const points = Number(body?.result?.points_count ?? body?.result?.vectors_count ?? 0);
const missing = status === 404 || response.error || !vectors;
if (!missing && (Number(vectors.size) !== 3072 || vectors.distance !== 'Cosine')) {
  throw new Error(`Qdrant schema mismatch for ${request.collection}; expected 3072/Cosine.`);
}
return [{ json: { ...request, collection_exists: !missing, points_count: missing ? 0 : points, setup_required: missing || points < 1 } }];

const input = $json;
return [{ json: {
  status: 'bootstrap_required',
  query: input.query,
  results: [],
  citations: [],
  bootstrap: {
    required: true,
    default_artifact: { source_key: input.default_artifact_source, collection: input.collection },
    workflow_id: 'govchat-ob-ingest-runner',
    action: 'Run the default artifact bootstrap workflow once; it creates the collection when missing and ingests the first durable page for the configured source.'
  },
  message: `Open Besluitvorming is nog niet beschikbaar. De standaardbron ${input.default_artifact_source} moet eerst worden ingeladen.`
} }];

const request = $('4. Determine Bootstrap State').first().json;
const sourceKeys = request.source_keys;
const must = [];
const any = (key, values) => { if (Array.isArray(values) && values.length) must.push({ key, match: { any: values } }); };
any('supplier', request.suppliers);
any('entity_type', request.entity_types);
any('classification', request.document_classifications);
any('meeting_id', request.meeting_ids);
any('document_id', request.document_ids);
if (request.date_from || request.date_to) {
  const range = {};
  if (request.date_from) range.gte = `${request.date_from}T00:00:00Z`;
  if (request.date_to) range.lte = `${request.date_to}T23:59:59Z`;
  must.push({ key: 'date', range });
}
const filter = {};
if (sourceKeys.length) filter.min_should = { conditions: sourceKeys.map(source_key => ({ key: 'source_key', match: { value: source_key } })), min_count: 1 };
if (must.length) filter.must = must;
if (request.date_only) return [{ json: { ...request, qdrant_filter: Object.keys(filter).length ? filter : undefined } }];
const embedding = $input.first()?.json?.data?.[0]?.embedding;
if (!Array.isArray(embedding) || embedding.length !== 3072) throw new Error('Embedding service returned no compatible 3072-dimensional vector.');
return [{ json: { ...request, embedding, qdrant_filter: Object.keys(filter).length ? filter : undefined } }];

const request = $('7. Build Filtered Vector Query').first().json;
const response = $input.first()?.json || {};
const raw = response.result?.points || response.points || response.result || [];
const received = Array.isArray(raw) ? raw : [];
const uuid = (value) => String(value || '').match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i)?.[0] || null;
const buildPublicUrl = (payload, pointId) => {
  if (payload.public_url) return String(payload.public_url);
  const nested = payload.source_payload || {};
  if (nested.public_url) return String(nested.public_url);
  const meetingId = uuid(payload.meeting_id || nested.meeting_id || nested.agenda_id);
  const documentId = uuid(payload.document_id || nested.document_id || payload.source_id || pointId);
  const configuredBase = String(payload.public_base_url || nested.public_base_url || nested.portal_base_url || '').replace(/\/$/, '');
  const sourceBase = payload.source_key === 'provincie_limburg' ? 'https://limburg.bestuurlijkeinformatie.nl' : '';
  const base = configuredBase || sourceBase;
  return base && meetingId && documentId ? `${base}/Agenda/Document/${meetingId}?documentId=${documentId}` : null;
};
const toResult = (point, index) => {
  const payload = point.payload || {};
  const content = String(payload.content_preview || payload.preview || payload.inhoud || payload.text || payload.tekst || payload.markdown_text || '');
  return { rank: index + 1, relevance_score: point.score == null ? null : Number(point.score), title: String(payload.title || payload.titel || payload.file_name || payload.bestandsnaam || 'Naamloos document'), date: payload.date || payload.datum || payload.datum_weergave || null, source_key: payload.source_key || payload.organization || null, supplier: payload.supplier || payload.source_payload?.supplier || null, classification: payload.classification || payload.source_payload?.classification || [], meeting_id: uuid(payload.meeting_id || payload.source_payload?.meeting_id), document_id: uuid(payload.document_id || payload.source_payload?.document_id || payload.source_id || point.id), public_url: buildPublicUrl(payload, point.id), excerpt: content.slice(0, 1200), ...(request.include_content ? { content } : {}) };
};
if (request.date_only) {
  if (received.length > 100) return [{ json: { status: 'topic_required', query: null, results: [], citations: [], retrieval: { strategy: 'date_only_scroll', matching_documents_at_least: received.length, safe_document_limit: 100, returned_documents: 0 }, message: 'Deze datumselectie bevat meer dan 100 documenten. Zonder onderwerp kan ik deze set niet betrouwbaar volledig analyseren. Voeg een inhoudelijk onderwerp toe aan query of maak de datumperiode kleiner.' } }];
  const chronological = received.slice().sort((a, b) => String(a.payload?.date || '').localeCompare(String(b.payload?.date || '')));
  const results = chronological.map(toResult);
  const citations = results.filter(item => item.public_url || item.document_id).map(item => ({ title: item.title, url: item.public_url, meeting_id: item.meeting_id, document_id: item.document_id, source_key: item.source_key }));
  return [{ json: { status: 'ok', query: null, collection: request.collection, source_keys: request.source_keys, results, citations, retrieval: { strategy: 'date_only_scroll', returned_documents: results.length, safe_document_limit: 100, date_from: request.date_from, date_to: request.date_to }, bootstrap: { required: false }, message: `Found all ${results.length} documents matching this date selection; results are chronological.` } }];
}
const points = received.slice().sort((a, b) => Number(b.score || 0) - Number(a.score || 0));
const topScore = Number(points[0]?.score || 0);
const absoluteFloor = 0.12;
const relativeFloor = topScore > 0 ? topScore * 0.58 : absoluteFloor;
const relevanceFloor = Math.max(absoluteFloor, relativeFloor);
const retained = points.filter((point) => Number(point.score || 0) >= relevanceFloor).slice(0, request.top_k);
const results = retained.map(toResult);
const citations = results.filter(item => item.public_url || item.document_id).map(item => ({ title: item.title, url: item.public_url, meeting_id: item.meeting_id, document_id: item.document_id, source_key: item.source_key }));
return [{ json: { status: 'ok', query: request.query, collection: request.collection, source_keys: request.source_keys, results, citations, retrieval: { candidate_limit: request.candidate_limit, candidates_received: points.length, relevance_floor: Number(relevanceFloor.toFixed(4)), returned_documents: results.length, max_returned_documents: request.top_k, strategy: 'adaptive_score_threshold' }, bootstrap: { required: false }, message: results.length ? `Found ${results.length} relevant Open Besluitvorming documents from ${points.length} candidates.` : 'No sufficiently relevant Open Besluitvorming documents were found.' } }];
